"use client";

import * as React from "react";

import { CallDetail } from "@/components/mockups/call-measurements/call-detail";
import { AppShell } from "@/components/shell/app-shell";
import { MockupShell } from "@/components/shell/mockup-shell";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { MEASUREMENT_CASES } from "@/lib/mockups/call-measurements-data";

export default function CallMeasurementsPage() {
  const [caseId, setCaseId] = React.useState(MEASUREMENT_CASES[0].id);
  const entry =
    MEASUREMENT_CASES.find((item) => item.id === caseId) ??
    MEASUREMENT_CASES[0];

  return (
    <MockupShell
      title="Measurements on each call"
      actions={
        <>
          <span className="text-xs text-muted-foreground">Case</span>
          <Select
            onValueChange={(value) => {
              const next = MEASUREMENT_CASES.find((item) => item.id === value);
              if (next) setCaseId(next.id);
            }}
            value={caseId}
          >
            <SelectTrigger aria-label="Call case" size="sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              {MEASUREMENT_CASES.map((item) => (
                <SelectItem key={item.id} value={item.id}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </>
      }
    >
      <AppShell
        active="Conversations"
        breadcrumb={["Conversations", "Call detail"]}
      >
        <main className="mx-auto flex w-full max-w-3xl flex-col p-3 lg:p-4">
          <CallDetail entry={entry} />
        </main>
      </AppShell>
    </MockupShell>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import type { MeasurementCase } from "@/lib/mockups/call-measurements-data";

import { CompletedIcon, OutboundIcon } from "./icons";
import { MeasurementsTab } from "./measurements-tab";

const SHIPPED_TABS = [
  "Overview",
  "Transcript",
  "Flags",
  "Details",
  "Model settings",
] as const;

export function CallDetail({ entry }: { entry: MeasurementCase }) {
  const { call } = entry;

  return (
    <div className="flex flex-col gap-4">
      <header className="flex items-start justify-between gap-4 border-b pb-4">
        <div className="flex min-w-0 flex-col gap-0.5">
          <h1 className="truncate text-xl font-semibold">{call.scenario}</h1>
          <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            <span className="flex items-center gap-1 font-medium text-foreground">
              <OutboundIcon className="size-3.5" />
              {call.phoneNumber}
            </span>
            <span aria-hidden>·</span>
            <span>{call.startedAt}</span>
            <span aria-hidden>·</span>
            <span>{call.duration}</span>
          </div>
        </div>
        <Badge className="bg-success-tint text-success-tint-foreground">
          <CompletedIcon />
          Completed
        </Badge>
      </header>

      <Tabs className="gap-6" defaultValue="measurements">
        <TabsList className="justify-start gap-3" variant="line">
          {SHIPPED_TABS.map((label) => (
            <TabsTrigger disabled key={label} value={label}>
              {label}
            </TabsTrigger>
          ))}
          <TabsTrigger value="measurements">Measurements</TabsTrigger>
        </TabsList>
        <TabsContent value="measurements">
          <MeasurementsTab measurements={entry.measurements} />
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import {
  AnalyticsDownIcon,
  CallOutgoing01Icon,
  CheckmarkCircle02Icon,
} from "@hugeicons/core-free-icons";

import { icon } from "@/components/shared/icon";

export const OutboundIcon = icon(CallOutgoing01Icon, "OutboundIcon");
export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon");
