"use client";

import {
  DataTable,
  DataTableHead,
  DataTableHeaderRow,
} from "@/components/shared/data-table";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import {
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  type CostLine,
  type Counter,
  firstSound,
  formatSeconds,
  formatUsd,
  type MeasurementCase,
  percentile,
  type Turn,
} from "@/lib/mockups/call-measurements-data";

import { NotMeasuredIcon } from "./icons";
import { TurnLatencyChart } from "./turn-latency-chart";

export function MeasurementsTab({
  measurements,
}: {
  measurements: MeasurementCase["measurements"];
}) {
  if (!measurements) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <NotMeasuredIcon />
          </EmptyMedia>
          <EmptyTitle>No measurements for this call</EmptyTitle>
          <EmptyDescription>
            Calls placed before Nov 12, 2026 were not measured.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      <CostCard lines={measurements.cost} />
      <LatencyCard
        fallbackModel={measurements.cost.find((line) => line.fallback)?.model}
        turns={measurements.turns}
      />
      <CountersCard counters={measurements.counters} />
    </div>
  );
}

function CostCard({ lines }: { lines: readonly CostLine[] }) {
  const known = lines.filter((line) => line.costUsd !== null);
  const missing = lines.filter((line) => line.costUsd === null);
  const total = known.reduce((sum, line) => sum + (line.costUsd ?? 0), 0);

  return (
    <Card>
      <CardHeader>
        <CardTitle>Cost</CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        <div className="flex flex-col gap-0.5">
          <span className="text-2xl font-semibold tabular-nums">
            {formatUsd(total)}
          </span>
          <span className="text-sm text-muted-foreground">
            {missing.length > 0
              ? `Our cost so far · excludes ${missing
                  .map((line) => line.component.toLowerCase())
                  .join(", ")}, not reported yet`
              : "Our cost"}
          </span>
        </div>

        <DataTable>
          <TableHeader>
            <DataTableHeaderRow>
              <DataTableHead>Component</DataTableHead>
              <DataTableHead>Model</DataTableHead>
              <DataTableHead>Usage</DataTableHead>
              <DataTableHead className="text-end">Cost</DataTableHead>
            </DataTableHeaderRow>
          </TableHeader>
          <TableBody>
            {lines.map((line, index) => {
              const sameGroup = lines[index - 1]?.component === line.component;

              return (
                <TableRow key={`${line.component}-${line.model}`}>
                  <TableCell>{sameGroup ? null : line.component}</TableCell>
                  <TableCell>
                    <span className="flex items-center gap-2">
                      {line.model}
                      {line.fallback ? (
                        <Badge variant="outline">Fallback</Badge>
                      ) : null}
                    </span>
                  </TableCell>
                  <TableCell className="text-muted-foreground">
                    {line.usage}
                  </TableCell>
                  <TableCell className="text-end tabular-nums">
                    {line.costUsd === null ? "—" : formatUsd(line.costUsd)}
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </DataTable>
      </CardContent>
    </Card>
  );
}

function LatencyCard({
  fallbackModel,
  turns,
}: {
  fallbackModel: string | undefined;
  turns: readonly Turn[];
}) {
  const sounds = turns.map(firstSound);
  const p95 = percentile(sounds, 95);
  const turnTaking =
    turns.reduce((sum, turn) => sum + turn.endOfSpeechWait, 0) / turns.length;

  const stats: Counter[] = [
    { label: "p50 latency", value: formatSeconds(percentile(sounds, 50)) },
    { label: "p75 latency", value: formatSeconds(percentile(sounds, 75)) },
    { label: "p95 latency", value: formatSeconds(p95) },
    { label: "Turn-taking latency", value: formatSeconds(turnTaking) },
  ];

  return (
    <Card>
      <CardHeader>
        <CardTitle>Latency</CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-6">
        <StatGrid stats={stats} />
        <div className="flex flex-col gap-1">
          <span className="text-sm font-medium">First sound by turn</span>
          <TurnLatencyChart
            fallbackModel={fallbackModel}
            p95={p95}
            turns={turns}
          />
        </div>
      </CardContent>
    </Card>
  );
}

function CountersCard({ counters }: { counters: readonly Counter[] }) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>Turns and tools</CardTitle>
      </CardHeader>
      <CardContent>
        <StatGrid stats={counters} />
      </CardContent>
    </Card>
  );
}

function StatGrid({ stats }: { stats: readonly Counter[] }) {
  return (
    <dl className="grid grid-cols-2 gap-x-4 gap-y-4 sm:grid-cols-4">
      {stats.map((stat) => (
        <div className="flex flex-col gap-0.5" key={stat.label}>
          <dt className="text-xs text-muted-foreground">{stat.label}</dt>
          <dd className="text-lg font-semibold tabular-nums">{stat.value}</dd>
          {stat.detail ? (
            <dd className="text-xs text-muted-foreground tabular-nums">
              {stat.detail}
            </dd>
          ) : null}
        </div>
      ))}
    </dl>
  );
}

"use client";

import {
  Bar,
  BarChart,
  CartesianGrid,
  ReferenceLine,
  XAxis,
  YAxis,
} from "recharts";

import { Card, CardContent } from "@/components/ui/card";
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
} from "@/components/ui/chart";
import {
  firstSound,
  formatSeconds,
  type Turn,
} from "@/lib/mockups/call-measurements-data";
import { cn } from "@/lib/utils";

const PARTS = [
  { key: "endOfSpeechWait", label: "End-of-speech wait", swatch: "bg-chart-1" },
  { key: "model", label: "Model", swatch: "bg-chart-2" },
  { key: "voice", label: "Voice", swatch: "bg-chart-3" },
] as const;

const CONFIG = {
  endOfSpeechWait: { label: "End-of-speech wait", color: "var(--chart-1)" },
  model: { label: "Model", color: "var(--chart-2)" },
  voice: { label: "Voice", color: "var(--chart-3)" },
} as const satisfies ChartConfig;

export function TurnLatencyChart({
  fallbackModel,
  p95,
  turns,
}: {
  fallbackModel: string | undefined;
  p95: number;
  turns: readonly Turn[];
}) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
        {PARTS.map((part) => (
          <span className="flex items-center gap-1.5" key={part.key}>
            <span
              aria-hidden
              className={cn("size-2 shrink-0 rounded-sm", part.swatch)}
            />
            {part.label}
          </span>
        ))}
        <span className="flex items-center gap-1.5">
          <span
            aria-hidden
            className="w-3 border-t border-dashed border-muted-foreground"
          />
          p95
        </span>
      </div>

      <ChartContainer className="aspect-auto h-56 w-full" config={CONFIG}>
        <BarChart
          accessibilityLayer
          barCategoryGap="28%"
          data={turns}
          margin={{ left: 0, right: 8, top: 8 }}
        >
          <CartesianGrid vertical={false} />
          <XAxis
            axisLine={false}
            dataKey="turn"
            tickLine={false}
            tickMargin={8}
          />
          <YAxis
            axisLine={false}
            tickFormatter={(value: number) => `${String(value)}s`}
            tickLine={false}
            width={32}
          />
          <ChartTooltip
            content={({ active, label }) => {
              const turn = turns.find((each) => each.turn === Number(label));
              if (!active || !turn) return null;
              return <TurnTooltip fallbackModel={fallbackModel} turn={turn} />;
            }}
            cursor={{ fill: "var(--color-muted)" }}
          />
          <ReferenceLine
            stroke="var(--color-muted-foreground)"
            strokeDasharray="4 4"
            y={p95}
          />
          {PARTS.map((part, index) => (
            <Bar
              dataKey={part.key}
              fill={`var(--color-${part.key})`}
              isAnimationActive={false}
              key={part.key}
              radius={index === PARTS.length - 1 ? [4, 4, 0, 0] : 0}
              stackId="turn"
              stroke="var(--color-card)"
              strokeWidth={1}
            />
          ))}
        </BarChart>
      </ChartContainer>
    </div>
  );
}

function TurnTooltip({
  fallbackModel,
  turn,
}: {
  fallbackModel: string | undefined;
  turn: Turn;
}) {
  return (
    <Card className="w-60 gap-2 text-xs" size="sm">
      <CardContent className="flex flex-col gap-2">
        <div className="flex flex-col gap-0.5">
          <span className="font-medium">Turn {turn.turn}</span>
          <span className="text-muted-foreground">“{turn.callerSaid}”</span>
        </div>
        <div className="flex flex-col gap-1">
          {PARTS.map((part) => (
            <div className="flex items-center gap-2" key={part.key}>
              <span
                aria-hidden
                className={cn("size-2 shrink-0 rounded-sm", part.swatch)}
              />
              <span className="text-muted-foreground">{part.label}</span>
              <span className="ms-auto tabular-nums">
                {formatSeconds(turn[part.key])}
              </span>
            </div>
          ))}
          <div className="flex items-center gap-2 border-t pt-1">
            <span className="font-medium">First sound</span>
            <span className="ms-auto font-medium tabular-nums">
              {formatSeconds(firstSound(turn))}
            </span>
          </div>
        </div>
        {turn.fallback && fallbackModel ? (
          <span className="text-muted-foreground">
            Fell back to {fallbackModel}
          </span>
        ) : null}
        {turn.interrupted ? (
          <span className="text-muted-foreground">Caller interrupted</span>
        ) : null}
      </CardContent>
    </Card>
  );
}

import * as React from "react";

import { Table, TableHead, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";

export function DataTable({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      <Table className={cn("[&_td]:h-10 [&_td]:px-4 [&_th]:px-4", className)}>
        {children}
      </Table>
    </div>
  );
}

export function DataTableHeaderRow({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <TableRow className="bg-muted/50 hover:bg-muted/50">{children}</TableRow>
  );
}

export function DataTableHead({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <TableHead className={cn("font-semibold text-foreground", className)}>
      {children}
    </TableHead>
  );
}

"use client";

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react";

/** No size of its own, so primitives size it through their `[&_svg]:size-4` rules. */
export function icon(glyph: IconSvgElement, displayName: string) {
  const Icon = (
    props: Omit<React.ComponentProps<typeof HugeiconsIcon>, "icon">,
  ) => <HugeiconsIcon icon={glyph} strokeWidth={1.8} {...props} />;
  Icon.displayName = displayName;
  return Icon;
}

